import{_ as l,C as e,o,c as n,a2 as a,b as p,w as s,a as d,E as u,a3 as i}from"./chunks/framework.BC3NdntU.js";const m=JSON.parse('{"title":"5.6 Rolldown / Rspack / Turbopack(Rust 系构建器)","description":"","frontmatter":{},"headers":[],"relativePath":"卷五-构建与工程化/5.6-Rolldown与Rspack与Turbopack.md","filePath":"卷五-构建与工程化/5.6-Rolldown与Rspack与Turbopack.md","lastUpdated":1788860986000}'),c={name:"卷五-构建与工程化/5.6-Rolldown与Rspack与Turbopack.md"};function b(R,t,k,h,g,w){const r=e("Mermaid");return o(),n("div",null,[t[1]||(t[1]=a('<h1 id="_5-6-rolldown-rspack-turbopack-rust-系构建器" tabindex="-1">5.6 Rolldown / Rspack / Turbopack(Rust 系构建器) <a class="header-anchor" href="#_5-6-rolldown-rspack-turbopack-rust-系构建器" aria-label="Permalink to &quot;5.6 Rolldown / Rspack / Turbopack(Rust 系构建器)&quot;">​</a></h1><blockquote><p>卷:卷五 · 构建与工程化 阅读时间:20min</p></blockquote><hr><h2 id="引言-构建工具的-第二场语言战争" tabindex="-1">引言:构建工具的&quot;第二场语言战争&quot; <a class="header-anchor" href="#引言-构建工具的-第二场语言战争" aria-label="Permalink to &quot;引言:构建工具的&quot;第二场语言战争&quot;&quot;">​</a></h2><p>从 Babel(JS)→ esbuild(Go)→ 现在 <strong>Rust</strong> 成了新宠。Rolldown、Rspack、Turbopack 都在用 Rust 重写构建器,目标是&quot;<strong>Rollup/webpack 的兼容 + esbuild 的速度</strong>&quot;。</p><hr><h2 id="一、三个-rust-构建器-一图" tabindex="-1">一、三个 Rust 构建器(一图) <a class="header-anchor" href="#一、三个-rust-构建器-一图" aria-label="Permalink to &quot;一、三个 Rust 构建器(一图)&quot;">​</a></h2>',7)),(o(),p(i,null,{default:s(()=>[u(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5BJS%20%E5%AE%9E%E7%8E%B0%5D%20--%3E%7CRust%20%E9%87%8D%E5%86%99%7C%20B%5BRust%20%E5%AE%9E%E7%8E%B0%5D%0A%20%20%20%20B%20--%3E%20C1%5BRolldown%3Cbr%2F%3ERollup%20%E5%85%BC%E5%AE%B9%20%E2%86%92%20Vite%5D%0A%20%20%20%20B%20--%3E%20C2%5BRspack%3Cbr%2F%3Ewebpack%20%E5%85%BC%E5%AE%B9%5D%0A%20%20%20%20B%20--%3E%20C3%5BTurbopack%3Cbr%2F%3ENext.js%20%E5%A2%9E%E9%87%8F%E6%89%93%E5%8C%85%5D%0A"})]),fallback:s(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a(`<table tabindex="0"><thead><tr><th>工具</th><th>出身</th><th>定位</th></tr></thead><tbody><tr><td>Rolldown</td><td>Vite 团队</td><td>Rollup 的 Rust 重写,Vite 未来内核</td></tr><tr><td>Rspack</td><td>字节</td><td>webpack 的 Rust 重写</td></tr><tr><td>Turbopack</td><td>Vercel</td><td>Next.js 增量打包器</td></tr></tbody></table><hr><h2 id="二、rolldown-vite-的下一个引擎-重点" tabindex="-1">二、Rolldown:Vite 的下一个引擎(重点) <a class="header-anchor" href="#二、rolldown-vite-的下一个引擎-重点" aria-label="Permalink to &quot;二、Rolldown:Vite 的下一个引擎(重点)&quot;">​</a></h2><p><strong>为什么需要 Rolldown?</strong> Vite 现在&quot;dev esbuild + build Rollup&quot;带来两个问题:</p><ol><li><strong>双引擎割裂</strong>:dev 和 build 行为不一致</li><li><strong>Rollup 是 JS 实现</strong>:大项目构建越来越慢成瓶颈</li></ol><p><strong>Rolldown 想做</strong>:用 Rust 重写 Rollup、保持 API 兼容,<strong>统一 esbuild + Rollup 为单一 Rust 引擎</strong>,dev/build 产物一致、全程极速。配套 <strong>Oxc</strong>(SWC 的 Rust 重写)做转译/lint/压缩。</p><hr><h2 id="三、rspack-turbopack" tabindex="-1">三、Rspack / Turbopack <a class="header-anchor" href="#三、rspack-turbopack" aria-label="Permalink to &quot;三、Rspack / Turbopack&quot;">​</a></h2><p><strong>Rspack</strong>:webpack 的 Rust 重写,<strong>兼容 webpack 的 loader/插件协议</strong>,存量项目近零成本迁移提速。</p><p><strong>Turbopack</strong>:Next.js 内置的增量打包器(基于 Rust)。</p><hr><h2 id="四、三者选型" tabindex="-1">四、三者选型 <a class="header-anchor" href="#四、三者选型" aria-label="Permalink to &quot;四、三者选型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>建议</th></tr></thead><tbody><tr><td>新项目/紧跟 Vite</td><td>关注 Rolldown 成熟度</td></tr><tr><td>存量 webpack 提速</td><td>Rspack 平滑迁移</td></tr><tr><td>Next.js 重度用户</td><td>Turbopack(内置)</td></tr></tbody></table><hr><h2 id="五、小结" tabindex="-1">五、小结 <a class="header-anchor" href="#五、小结" aria-label="Permalink to &quot;五、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Rust 重写构建器三主线:</span></span>
<span class="line"><span>Rolldown(Rollup 的 Rust 化 → 统一 Vite 双引擎)/ Rspack(webpack 兼容)/ Turbopack(Next.js)</span></span>
<span class="line"><span>核心诉求:Rust 拿 esbuild 级速度 + Rollup/webpack 级生态与产物</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><hr><h2 id="六、面试题" tabindex="-1">六、面试题 <a class="header-anchor" href="#六、面试题" aria-label="Permalink to &quot;六、面试题&quot;">​</a></h2><p><strong>Q1:为什么前端构建工具纷纷用 Rust 重写?</strong></p><p>JS 实现的打包器运行在 JS 引擎上,大项目越来越慢;<strong>Rust</strong> 编译型(近原生性能)、内存安全、并发强,重写后拿数倍到数十倍提速,同时通过 API 兼容保留现有生态(loader/插件)。</p><p><strong>Q2:Rolldown 和 Rollup 是什么关系?</strong></p><p>Rolldown 是 <strong>Rollup 的 Rust 重写</strong>,API 兼容(插件大多可复用),但用 Rust 拿数量级提速。由 Vite 团队打造,目标是<strong>替代 Vite 现在的&quot;esbuild + Rollup&quot;双引擎为单一内核</strong>。</p><p><strong>Q3:Vite 用 Rolldown 替代后,对开发者有什么好处?</strong></p><p>① dev 和 build <strong>行为/产物一致</strong>,减少&quot;dev 能跑 build 报错&quot;;② 构建速度大幅提升;③ 仍是 Vite,生态与心智不变,几乎无感升级。</p><p><strong>Q4:Rspack 相比 Rolldown 的定位差异?</strong></p><p>Rspack 兼容 <strong>webpack</strong>(loader/插件协议),目标是&quot;存量 webpack 项目提速迁移&quot;;Rolldown 兼容 <strong>Rollup</strong>,目标是&quot;Vite 的未来内核&quot;。一个 webpack 阵营,一个 Rollup/Vite 阵营。</p><p><strong>Q5:Rust 相比 Go(esbuild)重写构建器,优势在哪?</strong></p><p>都能拿原生性能;Rust 额外以<strong>内存安全 + 无 GC + 强并发</strong>著称,且能通过**原生绑定(N-API/Wasm)**嵌入 JS 工具链(Oxc 生态),更适合做长期演进的构建基础设施。</p><p><strong>Q6:现有项目要不要立刻迁移到 Rspack/Rolldown?</strong></p><p>看收益:<strong>存量 webpack 大项目、构建慢</strong>可试 Rspack(兼容好、迁移成本低);Rolldown 仍在成熟中,新项目可观望/小范围试用。原则:<strong>先测收益再迁移</strong>,别为追新而追新。</p><hr><p>📎 参考:Rolldown《Why Rolldown》、Rspack 文档、Turbopack 文档、VoidZero 博客</p>`,32))])}const E=l(c,[["render",b]]);export{m as __pageData,E as default};
